// Apply to SOFT_SKILLS_LONG_LESSONS
for (let d = 0; d < 5; d++) {
  const dayObj = SOFT_SKILLS_LONG_LESSONS[d];
  const dayNum = dayObj.day;
  for (let p = 0; p < 5; p++) {
    const key = `${dayNum}_${p}`;
    const extra = domainExpansions[key];
    if (extra && Array.isArray(dayObj.parts[p].say)) {
      (dayObj.parts[p].say as string[]).push(...extra);
    }
    let words = (dayObj.parts[p].say as string[]).reduce((acc, s) => acc + s.trim().split(/\s+/).filter(Boolean).length, 0);
    let insightIdx = 0;
    let followupIdx = 0;
    while (words < 600) {
      if (additionalInsights[dayNum] && insightIdx < additionalInsights[dayNum].length) {
        (dayObj.parts[p].say as string[]).push(additionalInsights[dayNum][insightIdx]);
        insightIdx++;
      } else if (followupIdx < domainFollowups.length) {
        (dayObj.parts[p].say as string[]).push(domainFollowups[followupIdx]);
        followupIdx++;
      } else {
        break;
      }
      words = (dayObj.parts[p].say as string[]).reduce((acc, s) => acc + s.trim().split(/\s+/).filter(Boolean).length, 0);
    }
    console.log(`Day ${dayNum} Part ${p + 1} (${dayObj.parts[p].title}): ${words} words`);
    if (words < 580) {
      throw new Error(`Day ${dayNum} Part ${p + 1} has ${words} words, must be >= 580`);
    }
  }
}

